\begin{proposition}[first rules]\label{prop:rules}
In a group $G$:
\begin{enumerate}[label=(\alph*)]
\item the identity is unique, and each $a$ has a unique inverse, written $a^{-1}$;
\item (cancellation) $ab=ac$ implies $b=c$, and $ba=ca$ implies $b=c$;
\item $(ab)^{-1}=b^{-1}a^{-1}$ and $(a^{-1})^{-1}=a$;
\item for $a,b\in G$ the equation $ax=b$ has exactly one solution, $x=a^{-1}b$. So in the multiplication table of a finite group, every row (and every column) contains each element exactly once.
\end{enumerate}
\end{proposition}

\begin{proposition}[rotations of the cube]\label{prop:cube}
The rotations of $\R^3$ that map the cube $[-1,1]^3$ to itself form a group of order $24$. Apart from the identity, they are: rotations by $\pm90^\circ$ and $180^\circ$ about the $3$ axes through the centres of opposite faces ($9$ rotations), by $\pm120^\circ$ about the $4$ long diagonals ($8$), and by $180^\circ$ about the $6$ axes through the midpoints of opposite edges ($6$).
\end{proposition}

\begin{proposition}\label{prop:subgroup}
\begin{enumerate}[label=(\alph*)]
\item A non-empty $H\subseteq G$ is a subgroup if and only if $ab^{-1}\in H$ for all $a,b\in H$.
\item An intersection of subgroups is a subgroup. For $S\subseteq G$, the intersection $\langle S\rangle$ of all subgroups containing $S$ is the set of finite products $s_1^{\pm1}\cdots s_k^{\pm1}$ with $s_i\in S$ (the empty product being $e$). It is the \emph{subgroup generated by $S$}.
\end{enumerate}
\end{proposition}

\begin{proposition}[order of an element]\label{prop:order}
Let $g\in G$. Either all the powers $g^k$, $k\in\Z$, are distinct, or there is a least $n\ge1$ with $g^n=e$, called the \emph{order} $o(g)$ of $g$. In the second case:
\begin{enumerate}[label=(\alph*)]
\item $g^k=e$ if and only if $n\mid k$, and $g^k=g^l$ if and only if $k\equiv l\pmod n$;
\item $\langle g\rangle=\{e,g,\dots,g^{n-1}\}$ has exactly $n$ elements;
\item $o(g^k)=\dfrac n{\gcd(n,k)}$.
\end{enumerate}
\end{proposition}

\begin{theorem}[Lagrange]\label{thm:lagrange}
Let $G$ be a finite group and $H\le G$. The left cosets of $H$ partition $G$, and each has $|H|$ elements. Hence
\[
\begin{gathered}|G|=[G:H]\cdot|H|,\qq\text{and in particular }|H|\text{ divides }|G|.\end{gathered}
\]
\end{theorem}

\begin{corollary}\label{cor:lagrange}
Let $G$ be finite of order $n$; in part (b), let $m\ge1$.
\begin{enumerate}[label=(\alph*)]
\item The order of every element divides $n$, and $g^n=e$ for all $g\in G$.
\item (Euler--Fermat, again) For $a$ coprime to $m$, $a^{\varphi(m)}\equiv1\pmod m$.
\item If $n$ is prime, $G$ is generated by any of its elements $g\ne e$.
\end{enumerate}
\end{corollary}

\begin{theorem}[cyclic groups]\label{thm:cyclic}
Let $G=\langle g\rangle$ be cyclic.
\begin{enumerate}[label=(\alph*)]
\item If $G$ is infinite, $k\mapsto g^k$ is an isomorphism $\Z\to G$. If $|G|=n$, $k\bmod n\mapsto g^k$ is an isomorphism $\Z/n\Z\to G$.
\item Every subgroup of $G$ is cyclic. If $|G|=n$, then for every divisor $d$ of $n$ there is exactly one subgroup of order $d$, namely $\langle g^{n/d}\rangle$, and there are no others.
\item If $|G|=n$, $g^k$ generates $G$ if and only if $\gcd(k,n)=1$. So $G$ has exactly $\varphi(n)$ generators, and exactly $\varphi(d)$ elements of order $d$ for each $d\mid n$.
\end{enumerate}
\end{theorem}

\begin{proposition}\label{prop:kerim}
Let $f:G\to G'$ be a homomorphism.
\begin{enumerate}[label=(\alph*)]
\item $\ker f$ is a subgroup of $G$ and $\operatorname{im}f$ a subgroup of $G'$.
\item $f(a)=f(b)$ if and only if $a\in b\ker f$. In particular $f$ is injective if and only if $\ker f=\{e\}$.
\item For $g\in G$ and $k\in\ker f$, $gkg^{-1}\in\ker f$.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{prop:normal}
For a subgroup $N\le G$, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item $N$ is normal;
\item $gNg^{-1}=N$ for every $g\in G$;
\item $gN=Ng$ for every $g\in G$: left and right cosets coincide.
\end{enumerate}
Kernels of homomorphisms are normal; every subgroup of an abelian group is normal; and a subgroup of index $2$ is normal.
\end{proposition}

\begin{theorem}[first isomorphism theorem]\label{thm:iso1}
Let $f:G\to G'$ be a homomorphism. Then $\bar f:G/\ker f\to\operatorname{im}f$, $g\ker f\mapsto f(g)$, is a well-defined isomorphism. In particular, for finite $G$, $|G|=|\ker f|\cdot|\operatorname{im}f|$.
\end{theorem}

\begin{theorem}[second and third isomorphism theorems, correspondence]\label{thm:iso23}
Let $N\trianglelefteq G$ and $\pi:G\to G/N$.
\begin{enumerate}[label=(\alph*)]
\item (Correspondence) $H\mapsto H/N=\pi(H)$ is a bijection from the subgroups of $G$ containing $N$ to the subgroups of $G/N$, which preserves inclusions and normality.
\item (Third theorem) If $N\le M\trianglelefteq G$, then $(G/N)/(M/N)\cong G/M$.
\item (Second theorem) If $H\le G$, then $HN=\{hn\}$ is a subgroup of $G$, $H\cap N\trianglelefteq H$, and $H/(H\cap N)\cong HN/N$.
\end{enumerate}
\end{theorem}

\begin{theorem}[Chinese remainder theorem, group version]\label{thm:crt}
For positive integers $m,n$, $\Z/mn\Z\cong\Z/m\Z\times\Z/n\Z$ if and only if $\gcd(m,n)=1$.
\end{theorem}

\begin{proposition}[internal direct product]\label{prop:internal}
Let $H,K$ be normal subgroups of $G$ with $H\cap K=\{e\}$ and $HK=G$. Then $hk=kh$ for $h\in H$, $k\in K$, and $(h,k)\mapsto hk$ is an isomorphism $H\times K\to G$.
\end{proposition}

\begin{proposition}\label{prop:semidirect}
\begin{enumerate}[label=(\alph*)]
\item $N\rtimes_\varphi H$ is a group, with $|N||H|$ elements if the factors are finite, in which $N\times\{e\}$ is a normal subgroup isomorphic to $N$, $\{e\}\times H$ a subgroup isomorphic to $H$, and $(e,h)(n,e)(e,h)^{-1}=(\varphi_h(n),e)$.
\item (Recognition) If $N\trianglelefteq G$, $H\le G$, $N\cap H=\{e\}$ and $NH=G$, then $G\cong N\rtimes_\varphi H$ with $\varphi_h(n)=hnh^{-1}$.
\end{enumerate}
\end{proposition}

\begin{theorem}[Cayley]\label{thm:cayley}
Every group $G$ is isomorphic to a subgroup of $\mathfrak S(G)$. In particular every group of order $n$ is isomorphic to a subgroup of $\mathfrak S_n$.
\end{theorem}

\begin{theorem}[Burnside's lemma]\label{thm:burnside}
Let a finite group $G$ act on a finite set $X$. The number of orbits is the average number of fixed points:
\[
|X/G|=\frac1{|G|}\sum_{g\in G}|X^g|.
\]
\end{theorem}

\begin{corollary}\label{cor:pgroup}
The centre of a nontrivial $p$-group is not trivial.
\end{corollary}

\begin{theorem}[Cauchy]\label{thm:cauchy}
If a prime $p$ divides the order of a finite group $G$, then $G$ has an element of order $p$.
\end{theorem}

\begin{proposition}[cycle decomposition]\label{prop:cycles}
Every $\sigma\in\mathfrak S_n$ is a product of pairwise disjoint cycles. The factors are unique up to their order and the choice of starting entry in each written cycle; fixed points are omitted.
\end{proposition}

\begin{corollary}\label{cor:ordersign}
Let $\sigma$ have cycle type $(k_1,\dots,k_r)$ (so $k_1+\dots+k_r=n$). Then
\begin{enumerate}[label=(\alph*)]
\item the order of $\sigma$ is $\operatorname{lcm}(k_1,\dots,k_r)$;
\item $\varepsilon(\sigma)=\prod_i(-1)^{k_i-1}=(-1)^{n-r}$. In particular a $k$-cycle is even iff $k$ is odd.
\end{enumerate}
\end{corollary}

\begin{proposition}\label{prop:gens}
\begin{enumerate}[label=(\alph*)]
\item $\mathfrak S_n$ is generated by the adjacent transpositions $(1\,2),(2\,3),\dots,(n-1\;n)$.
\item For $n\ge3$, $A_n$ is generated by the $3$-cycles.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{prop:a4}
$A_4$ has order $12$ and no subgroup of order $6$. So the converse of Lagrange's theorem is false.
\end{proposition}

\begin{theorem}\label{thm:fifteen}
For a position $\sigma$, let $\delta(\sigma)=+1$ if the blank is on a white cell and $-1$ otherwise.
\begin{enumerate}[label=(\alph*)]
\item $\varepsilon(\sigma)\delta(\sigma)$ does not change under moves.
\item A position can be reached from the solved position iff $\varepsilon(\sigma)\delta(\sigma)=1$. Exactly half of the $16!$ positions can be reached; the position with $14$ and $15$ swapped cannot.
\end{enumerate}
\end{theorem}

\begin{lemma}\label{lem:split}
Let $n\ge2$, $\sigma\in A_n$, and let $C$ be its conjugacy class in $\mathfrak S_n$. If the centraliser $C(\sigma)$ in $\mathfrak S_n$ contains an odd permutation, $C$ is a single conjugacy class of $A_n$. Otherwise $C$ splits into two classes of $A_n$ of size $|C|/2$ each.
\end{lemma}

\begin{theorem}\label{thm:a5}
$A_5$ is simple. Its conjugacy classes have sizes $1,15,20,12,12$.
\end{theorem}

\begin{theorem}\label{thm:an}
$A_n$ is simple for every $n\ge5$.
\end{theorem}

\begin{theorem}[Sylow I]\label{thm:sylow1}
If $G$ is finite and $|G|=p^a m$ with $p\nmid m$, then $G$ has a subgroup of order $p^a$.
\end{theorem}

\begin{theorem}[Sylow II and III]\label{thm:sylow23}
Let $P$ be a Sylow $p$-subgroup of $G$.
\begin{enumerate}[label=(\alph*)]
\item Every $p$-subgroup of $G$ is contained in a conjugate of $P$.
\item The Sylow $p$-subgroups are exactly the conjugates of $P$.
\item $n_p=[G:N_G(P)]$, so $n_p$ divides $m$; and $n_p\equiv1\pmod p$.
\end{enumerate}
\end{theorem}

\begin{corollary}\label{cor:sylownormal}
A Sylow $p$-subgroup $P$ is normal iff $n_p=1$. In that case $P$ contains every $p$-subgroup of $G$, and every element of order a power of $p$.
\end{corollary}

\begin{corollary}\label{cor:pk}
If $k\ge0$ is an integer and $p^k$ divides $|G|$, then $G$ has a subgroup of order $p^k$.
\end{corollary}

\begin{proposition}\label{prop:thirty}
No group of order $30$ is simple.
\end{proposition}

\begin{theorem}[groups of order $pq$]\label{thm:pq}
Let $p<q$ be primes and $|G|=pq$.
\begin{enumerate}[label=(\alph*)]
\item If $p\nmid q-1$, then $G\cong\Z/pq\Z$.
\item If $p\mid q-1$, then $G$ is either cyclic or isomorphic to the non-abelian semidirect product $\Z/q\Z\rtimes_u\Z/p\Z$, where $b\in\Z/p\Z$ acts on $\Z/q\Z$ as multiplication by $u^b$ and $u$ is any element of order $p$ in $(\Z/q\Z)^*$; this group does not depend on the choice of $u$.
\end{enumerate}
In particular every group of order $2q$ ($q$ an odd prime) is $\Z/2q\Z$ or the dihedral group $D_q$.
\end{theorem}

\begin{proposition}\label{prop:solv}
\begin{enumerate}[label=(\alph*)]
\item Subgroups and quotients of a solvable group are solvable.
\item If $N\trianglelefteq G$ and both $N$ and $G/N$ are solvable, then $G$ is solvable.
\item Every $p$-group is solvable. Every group of order $pq$, with $p,q$ prime, is solvable.
\item A non-abelian simple group is not solvable. In particular $A_n$ and $\mathfrak S_n$ are not solvable for $n\ge5$.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{prop:finitedomain}
A finite integral domain is a field.
\end{proposition}

\begin{proposition}[quotient rings]\label{prop:quotring}
Let $I$ be any ideal of $R$, including $I=R$.
\begin{enumerate}[label=(\alph*)]
\item The quotient group $R/I$ is a ring with $(a+I)(b+I)=ab+I$, and $\pi:a\mapsto a+I$ is a ring homomorphism with kernel $I$.
\item (First isomorphism theorem) If $f:R\to S$ is a ring homomorphism, $R/\ker f\cong f(R)$.
\item (Correspondence) $J\mapsto J/I$ is a bijection from the ideals of $R$ containing $I$ to the ideals of $R/I$.
\end{enumerate}
\end{proposition}

\begin{proposition}\label{prop:primemax}
Let $I\ne R$ be an ideal.
\begin{enumerate}[label=(\alph*)]
\item $I$ is prime iff $R/I$ is an integral domain.
\item $I$ is maximal iff $R/I$ is a field.
\item Every maximal ideal is prime.
\end{enumerate}
\end{proposition}

\begin{theorem}[Chinese remainder theorem for rings]\label{thm:crtring}
Write $I+J=\{i+j:i\in I,j\in J\}$, an ideal by addition and absorption.
Let $I,J$ be ideals with $I+J=R$ (they are \emph{coprime}). Then $I\cap J=IJ$, where $IJ$ is the ideal generated by the products $ab$, $a\in I$, $b\in J$, and
\[
\begin{gathered}R/(I\cap J)\cong R/I\times R/J,\qq x+I\cap J\mapsto(x+I,\,x+J).\end{gathered}
\]
If $n\ge1$ and $I_1,\dots,I_n$ are pairwise coprime, $R/(I_1\cap\dots\cap I_n)\cong\prod_kR/I_k$.
\end{theorem}

\begin{proposition}\label{prop:zm5}
In $\Z[\sqrt{-5}]$, with the norm $N(a+b\sqrt{-5})=a^2+5b^2=|a+b\sqrt{-5}|^2$:
\begin{enumerate}[label=(\alph*)]
\item $N(xy)=N(x)N(y)$, the units are $\pm1$, and no element has norm $2$ or $3$;
\item $2$, $3$, $1+\sqrt{-5}$ and $1-\sqrt{-5}$ are irreducible, and no two of them are associates;
\item $2$ is irreducible but not prime. So $\Z[\sqrt{-5}]$ is not a UFD.
\end{enumerate}
\end{proposition}

\begin{lemma}\label{lem:primeufd}
In a domain, if $a=p_1\cdots p_r=q_1\cdots q_s$ with the $p_i$ prime and the $q_j$ irreducible, then $r=s$ and, after reordering, $q_i$ is an associate of $p_i$. Hence a domain in which every non-zero non-unit is a product of irreducibles is a UFD iff every irreducible is prime.
\end{lemma}

\begin{theorem}\label{thm:edpidufd}
Euclidean $\Rightarrow$ PID $\Rightarrow$ UFD.
\end{theorem}

\begin{lemma}[Gauss]\label{lem:gauss}
Let $R$ be a UFD. A product of primitive polynomials is primitive; hence $c(fg)=c(f)c(g)$ up to units.
\end{lemma}

\begin{proposition}\label{prop:gaussirr}
Let $R$ be a UFD with fraction field $K$, and $f\in R[X]$ primitive of degree $\ge1$. Then $f$ is irreducible in $R[X]$ iff it is irreducible in $K[X]$. If $f$ divides $g\in R[X]$ in $K[X]$, it divides $g$ in $R[X]$.
\end{proposition}

\begin{theorem}[Gauss]\label{thm:gaussufd}
If $R$ is a UFD, so is $R[X]$. In particular $\Z[X]$ and $K[X_1,\dots,X_n]$ are UFDs.
\end{theorem}

\begin{theorem}[Smith normal form]\label{thm:smith}
Let $m,n\ge0$ and let $A$ be an $m\times n$ matrix over a PID $R$. There are $P\in GL_m(R)$ and $Q\in GL_n(R)$ such that
\[
\begin{gathered}PAQ=\begin{pmatrix}D&0\\0&0\end{pmatrix},\qq D=\operatorname{diag}(d_1,\dots,d_r),\\ d_i\ne0,\quad d_1\mid d_2\mid\dots\mid d_r.\end{gathered}
\]
The number $r$ and the $d_i$ (up to units) are determined by $A$: if $\Delta_k(A)$ denotes a gcd of the $k\times k$ minors of $A$, then $d_1\cdots d_k=\Delta_k(A)$ up to a unit for $1\le k\le r$, and $\Delta_k(A)=0$ for $r<k\le\min(m,n)$. We put $\Delta_0(A)=1$.
\end{theorem}

\begin{lemma}\label{lem:subfree}
Over a PID, every submodule of $R^n$ is free of rank at most $n$.
\end{lemma}

\begin{corollary}[finitely generated abelian groups]\label{cor:abelian}
Every finitely generated abelian group is isomorphic to $\Z^s\oplus\Z/d_1\Z\oplus\dots\oplus\Z/d_r\Z$ with $1<d_1\mid\dots\mid d_r$, and also to $\Z^s\oplus\bigoplus_j\Z/p_j^{a_j}\Z$ with prime powers $p_j^{a_j}$; $s$, the $d_i$, and the multiset of the $p_j^{a_j}$ are unique. In particular, for $n\ge1$ with $n=\prod p^{a_p}$, the number of abelian groups of order $n$ is $\prod_p\mathrm{p}(a_p)$, where $\mathrm p(a)$ is the number of partitions of $a$.
\end{corollary}

\begin{corollary}\label{cor:index}
If $A\in M_n(\Z)$ has $\det A\ne0$, the subgroup $A\Z^n$ has index $|\det A|$ in $\Z^n$, and $\Z^n/A\Z^n\cong\bigoplus\Z/d_i\Z$ with the $d_i$ of the Smith form.
\end{corollary}

\begin{theorem}[rational canonical form; Frobenius]\label{thm:frobenius}
Every $A\in M_n(K)$ is similar to the block diagonal matrix $\operatorname{diag}(C(d_1),\dots,C(d_r))$ of its invariant factors. Two matrices are similar iff they have the same invariant factors. For $n\ge1$ the minimal polynomial is $\mu_A=d_r$, and $\chi_A=d_1\cdots d_r$. For $n=0$ the block list is empty and both polynomials are $1$.
\end{theorem}

\begin{corollary}[Cayley--Hamilton]\label{cor:cayleyhamilton}
$\chi_A(A)=0$. Moreover $\mu_A$ divides $\chi_A$, and they have the same irreducible factors.
\end{corollary}

\begin{theorem}[Jordan normal form]\label{thm:jordan}
If $\chi_A$ splits over $K$, then $A$ is similar to a block diagonal matrix of Jordan blocks $J_{e}(\lambda)$, unique up to the order of the blocks. The blocks for $\lambda$ have sizes $e_{1,\lambda}\le\dots\le e_{r,\lambda}$ (the non-zero ones), the exponents of $X-\lambda$ in the invariant factors.
\end{theorem}

\begin{corollary}\label{cor:towerdiv}
If $K\subseteq L\subseteq M$ and $M/K$ is finite, then $[L:K]$ and $[M:L]$ divide $[M:K]$. In particular, if $[M:K]$ is prime, there is no intermediate field other than $K$ and $M$.
\end{corollary}

\begin{corollary}\label{cor:finitealg}
A finite extension $L/K$ is algebraic, and the degree of each $\alpha\in L$ divides $[L:K]$. Conversely, if $\alpha_1,\dots,\alpha_n$ are algebraic over $K$, then $K(\alpha_1,\dots,\alpha_n)/K$ is finite.
\end{corollary}

\begin{theorem}[Kronecker]\label{thm:kronecker}
Let $P\in K[X]$ be irreducible of degree $d$. Then $L=K[X]/(P)$ is a field; $c\mapsto c+(P)$ identifies $K$ with a subfield of $L$; the class $x=X+(P)$ is a root of $P$ in $L$; and $L=K(x)$, $[L:K]=d$. Consequently every non-constant polynomial over $K$ has a root in some finite extension of $K$.
\end{theorem}

\begin{proposition}\label{prop:splitexists}
Every $P\in K[X]$ of degree $n\ge1$ has a splitting field $L$, with $[L:K]\le n!$.
\end{proposition}

\begin{lemma}\label{lem:extend1}
Let $\sigma:K\to K'$ be an isomorphism, $Q\in K[X]$ irreducible, $\alpha$ a root of $Q$ in an extension of $K$ and $\beta$ a root of $\sigma Q$ in an extension of $K'$. There is exactly one isomorphism $\tau:K(\alpha)\to K'(\beta)$ that extends $\sigma$ and sends $\alpha$ to $\beta$.
\end{lemma}

\begin{lemma}\label{lem:sep}
Let $K$ have characteristic $0$ and $Q\in K[X]$ be irreducible. Then $Q$ has distinct roots in every extension of $K$.
\end{lemma}

\begin{theorem}[uniqueness of splitting fields]\label{thm:splitunique}
Let $\sigma:K\to K'$ be an isomorphism, $P\in K[X]$ of degree $\ge1$, $L$ a splitting field of $P$ over $K$ and $L'$ a splitting field of $\sigma P$ over $K'$. Then $\sigma$ extends to an isomorphism $L\to L'$, and the number of such extensions is at most $[L:K]$, with equality if $\sigma P$ has distinct roots in $L'$.
In particular a splitting field is unique up to isomorphism, and if $P$ has distinct roots in $L$, then $L$ has exactly $[L:K]$ automorphisms that fix $K$ pointwise.
\end{theorem}

\begin{proposition}\label{prop:constrfield}
The constructible numbers form a subfield $\mathcal C$ of $\C$, closed under complex conjugation and under square roots. A complex number $x+iy$ ($x,y$ real) is constructible iff $x$ and $y$ are.
\end{proposition}

\begin{corollary}[the classical problems]\label{cor:classical}
\begin{enumerate}[label=(\alph*)]
\item (Doubling the cube) $\sqrt[3]2$ is not constructible.
\item (Trisection) The angle $60^\circ$, which is constructible, cannot be trisected: $\cos20^\circ$ is not constructible.
\item (Polygons) The regular pentagon is constructible; the regular heptagon is not. More generally, if $p\ge3$ is a prime and the regular $p$-gon is constructible, then $p-1$ is a power of $2$.
\end{enumerate}
\end{corollary}

\begin{theorem}[primitive element]\label{thm:primitiveelement}
Let $K\subseteq\C$ be a field and $\alpha,\beta\in\C$ algebraic over $K$. There is $c\in\Q$ such that $K(\alpha,\beta)=K(\alpha+c\beta)$. Consequently every finite extension $L/K$ of subfields of $\C$ is of the form $K(\gamma)$.
\end{theorem}

\begin{proposition}\label{prop:primefield}
Let $K$ be a finite field. There is a prime $p$, the \emph{characteristic} of $K$, such that $p\cdot1=0$ in $K$; the subring generated by $1$ is a field isomorphic to $\mathbb F_p=\Z/p\Z$, the \emph{prime field} of $K$; and $|K|=p^n$, where $n=[K:\mathbb F_p]$.
\end{proposition}

\begin{lemma}[Frobenius]\label{lem:frob}
Let $K$ be a field of characteristic $p$. Then $(a+b)^p=a^p+b^p$ for all $a,b\in K$, and $\varphi:x\mapsto x^p$ is an injective ring homomorphism $K\to K$ that fixes $\mathbb F_p$. If $K$ is finite, $\varphi$ is an automorphism of $K$, the \emph{Frobenius automorphism}.
\end{lemma}

\begin{theorem}\label{thm:cyclicmult}
Let $K$ be a field. Every finite subgroup $G$ of $K^*$ is cyclic. In particular, if $K$ is finite with $q$ elements, $K^*$ is cyclic of order $q-1$.
\end{theorem}

\begin{lemma}\label{lem:xqx}
If $K$ is a field with $q$ elements, then $x^q=x$ for every $x\in K$, and
\[
X^q-X=\prod_{a\in K}(X-a)\quad\text{in }K[X].
\]
\end{lemma}

\begin{theorem}[Galois, Moore]\label{thm:fq}
For every prime $p$ and $n\ge1$ there is a field with $q=p^n$ elements, and any two such fields are isomorphic: it is the splitting field of $X^q-X$ over $\mathbb F_p$. We denote it by $\mathbb F_q$.
\end{theorem}

\begin{theorem}\label{thm:subfields}
The subfields of $\mathbb F_{p^n}$ are the sets $\{x:x^{p^d}=x\}$ for $d\mid n$; there is exactly one subfield with $p^d$ elements for each divisor $d$ of $n$, and no other.
\end{theorem}

\begin{theorem}\label{thm:galfq}
The automorphisms of $\mathbb F_{p^n}$ form a cyclic group of order $n$, generated by the Frobenius automorphism $\varphi$.
\end{theorem}

\begin{theorem}\label{thm:xqnx}
For $n\ge1$, in $\mathbb F_q[X]$, $X^{q^n}-X$ is the product of all monic irreducible polynomials whose degree divides $n$.
\end{theorem}

\begin{proposition}\label{prop:rsdist}
Two different codewords are at distance at least $n-k+1$. Consequently, if at most $t=\lfloor\frac{n-k}2\rfloor$ symbols are corrupted, the sent codeword is the unique codeword closest to the received word.
\end{proposition}

\begin{lemma}\label{lem:permroots}
Let $\sigma\in\operatorname{Gal}(L/K)$ and $P\in K[X]$. If $\alpha\in L$ is a root of $P$, so is $\sigma(\alpha)$. Consequently, if $L=K(\alpha_1,\dots,\alpha_n)$ where $\alpha_1,\dots,\alpha_n$ are the distinct roots of a nonzero polynomial $P$, then $\sigma\mapsto(\sigma\text{ restricted to the roots})$ is an injective homomorphism $\operatorname{Gal}(L/K)\to\mathfrak S_n$.
\end{lemma}

\begin{proposition}\label{prop:autbound}
For every finite extension, $|\operatorname{Gal}(L/K)|\le[L:K]$.
\end{proposition}

\begin{theorem}\label{thm:galoischar}
For a finite extension $K\subseteq L\subseteq\C$, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item $L$ is the splitting field over $K$ of some polynomial of $K[X]$;
\item $L/K$ is Galois;
\item $L^{\operatorname{Gal}(L/K)}=K$;
\item ($L/K$ is \emph{normal}) every irreducible polynomial of $K[X]$ with a root in $L$ splits in $L$.
\end{enumerate}
\end{theorem}

\begin{lemma}[Artin]\label{lem:artin}
Let $L/K$ be finite and $H$ a subgroup of $\operatorname{Gal}(L/K)$. Then $[L:L^H]=|H|$ and $\operatorname{Gal}(L/L^H)=H$.
\end{lemma}

\begin{proposition}\label{prop:cyclo}
For every subfield $K\subseteq\C$, the extension $K(\zeta_n)/K$ is Galois, and $\sigma\mapsto a_\sigma$, where $\sigma(\zeta_n)=\zeta_n^{a_\sigma}$, is an injective homomorphism $\operatorname{Gal}(K(\zeta_n)/K)\to(\Z/n\Z)^*$. In particular this Galois group is abelian. For $K=\Q$ and $n=p$ prime, it is an isomorphism, and $\operatorname{Gal}(\Q(\zeta_p)/\Q)$ is cyclic of order $p-1$.
\end{proposition}

\begin{theorem}[Gauss, Wantzel]\label{thm:gw}
For an integer $n\ge3$, if $\varphi(n)$ is a power of $2$, the regular $n$-gon is constructible with ruler and compass. In particular the $p$-gon is constructible for every Fermat prime $p=2^{2^k}+1$: $3$, $5$, $17$, $257$, $65537$.
\end{theorem}

\begin{lemma}\label{lem:kummerstep}
Let $m\ge1$, let $F\subseteq\C$ contain $\zeta_m$, and let $b\in\C$ with $b^m=c\in F$. Then $F(b)/F$ is Galois with abelian Galois group.
\end{lemma}

\begin{theorem}[Galois]\label{thm:radsolv}
If a nonzero $P\in K[X]$ is solvable by radicals, its Galois group is solvable.
\end{theorem}

\begin{theorem}[Abel, Ruffini]\label{thm:abelruffini}
The Galois group of $X^5-4X+2$ over $\Q$ is $\mathfrak S_5$. Consequently its roots cannot be expressed by radicals, and there is no formula in radicals for the roots of the general quintic.
\end{theorem}

\begin{lemma}[Dedekind]\label{lem:dedekind}
Distinct automorphisms $\sigma_1,\dots,\sigma_n$ of a field $L$ are linearly independent over $L$: if $c_1\sigma_1(x)+\dots+c_n\sigma_n(x)=0$ for all $x\in L$, with $c_i\in L$, then all $c_i=0$.
\end{lemma}

\begin{proposition}[Kummer]\label{prop:kummer}
Let $m\ge1$, let $F\subseteq\C$ contain $\zeta_m$, and let $E/F$ be Galois with cyclic group of order $m$. Then $E=F(\theta)$ for some $\theta$ with $\theta^m\in F$.
\end{proposition}

\begin{theorem}[Galois' criterion]\label{thm:galoiscrit}
For $K\subseteq\C$ and a nonzero $P\in K[X]$, $P$ is solvable by radicals iff its Galois group is solvable.
\end{theorem}

\begin{theorem}[Maschke]\label{thm:maschke}
For finite $G$, every complex representation $V$ has a $G$-invariant Hermitian inner product: $\langle gv,gw\rangle=\langle v,w\rangle$. Consequently every stable subspace $W$ has a stable complement $W^\perp$, and $V$ is a direct sum of irreducible subrepresentations.
\end{theorem}

\begin{lemma}[Schur]\label{lem:schur}
Let $V,V'$ be irreducible and $f:V\to V'$ an intertwiner. Then $f=0$ or $f$ is an isomorphism. If $V=V'$, then $f=\lambda\,\mathrm{id}$ for some $\lambda\in\C$.
\end{lemma}

\begin{corollary}\label{cor:abelianirr}
If $G$ is abelian, every irreducible representation has dimension $1$.
\end{corollary}

\begin{proposition}\label{prop:charbasic}
\begin{enumerate}[label=(\alph*)]
\item $\chi(e)=\dim V$; $\chi$ is a class function; isomorphic representations have the same character.
\item $\chi(g^{-1})=\overline{\chi(g)}$, and $|\chi(g)|\le\chi(e)$.
\item $\chi_{V\oplus W}=\chi_V+\chi_W$.
\item For a permutation representation $\C^X$, $\chi(g)$ is the number of fixed points of $g$ on $X$. In particular the character of $\C[G]$ is $|G|$ at $e$ and $0$ elsewhere.
\end{enumerate}
\end{proposition}

\begin{theorem}[orthogonality of characters]\label{thm:orth}
Let $\chi,\chi'$ be the characters of irreducible representations $V,V'$. Then $\langle\chi,\chi'\rangle=1$ if $V\cong V'$, and $0$ otherwise.
\end{theorem}

\begin{corollary}\label{cor:mult}
Let $V_1,\dots,V_r$ be pairwise non-isomorphic irreducible representations with characters $\chi_1,\dots,\chi_r$, and $V$ any representation.
\begin{enumerate}[label=(\alph*)]
\item In any decomposition of $V$ into irreducibles, the number of summands isomorphic to $V_i$ is $\langle\chi_V,\chi_i\rangle$. So two representations with the same character are isomorphic.
\item $V$ is irreducible iff $\langle\chi_V,\chi_V\rangle=1$.
\item (Regular representation) Every irreducible $V_i$ occurs in $\C[G]$, $\dim V_i$ times. Hence there are finitely many irreducible representations up to isomorphism, and if $V_1,\dots,V_r$ is the full list, $\sum_i(\dim V_i)^2=|G|$.
\end{enumerate}
\end{corollary}

\begin{theorem}\label{thm:classes}
The irreducible characters form an orthonormal basis of the space of class functions. In particular, the number of irreducible representations of $G$ is the number of its conjugacy classes.
\end{theorem}

\begin{corollary}[column orthogonality]\label{cor:columns}
Let $\chi_1,\dots,\chi_r$ be the irreducible characters, and $g,h\in G$. Then $\sum_i\chi_i(g)\overline{\chi_i(h)}$ is $|C_G(g)|$ if $g$ and $h$ are conjugate, and $0$ otherwise.
\end{corollary}

\begin{theorem}[Fourier analysis on a finite abelian group]\label{thm:fourier}
For $f:A\to\C$ define $\hat f(\chi)=\langle f,\chi\rangle=\frac1{|A|}\sum_{a}f(a)\overline{\chi(a)}$. Then
\[
\begin{gathered}f=\sum_{\chi\in\widehat A}\hat f(\chi)\,\chi,\qq\frac1{|A|}\sum_{a\in A}|f(a)|^2=\sum_{\chi\in\widehat A}|\hat f(\chi)|^2,\end{gathered}
\]
and for $a\in A$,
\[
\frac1{|A|}\sum_{\chi\in\widehat A}\chi(a)=\begin{cases}1&\text{if }a=0,\\0&\text{otherwise.}\end{cases}
\]
\end{theorem}

\begin{proposition}\label{prop:dirichletorth}
Let $a$ be prime to $q$. For every integer $n$,
\[
\frac1{\varphi(q)}\sum_{\chi\bmod q}\overline{\chi(a)}\,\chi(n)=\begin{cases}1&\text{if }n\equiv a\ (q),\\0&\text{otherwise.}\end{cases}
\]
\end{proposition}
